n.exploreUrl:
@js:
var result = [];
var push = (title, url, size) => result.push({
    "title": title,
    "url": url,
    "style": {
        "layout_flexGrow": 1,
        "layout_flexBasisPercent": size
    }
});
var baseUrl = "https://www.bookjisu.com"; 
var tag = java.ajax(baseUrl);
if (tag) {
    a = org.jsoup.Jsoup.parse(tag).select(".navbar-nav a");
    push("🔥分类小说🔥", null, 1);
    for (i in a) {
        title = a[i].text();
        url = a[i].attr("href");
        size = 0.33;
        title = String(title).replace(/\s/g, ""); 
        url = baseUrl + String(url).replace(/\/$/, "") + "/{{page}}.html"; 
        push(title, url, size);
    }
} 
JSON.stringify(result);

